#include <string>
#include <cstdlib>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> pts(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> pts[i][j];
        }
    }

    const long long INF = 1000000000000000000LL;
    vector<long long> best(n, INF);
    vector<char> used(n, 0);
    best[0] = 0;
    long long total = 0;
    for (int round = 0; round < n; round++) {
        int u = -1;
        for (int v = 0; v < n; v++) {
            if (!used[v] && (u == -1 || best[v] < best[u])) u = v;
        }
        used[u] = 1;
        total += best[u];
        for (int v = 0; v < n; v++) {
            if (!used[v]) {
                long long d = llabs(pts[u][0] - pts[v][0]) + llabs(pts[u][1] - pts[v][1]);
                if (d < best[v]) best[v] = d;
            }
        }
    }
    cout << total << "\n";

    return 0;
}

