import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] pts = new long[(int) n][2];
        for (int i = 0; i < pts.length; i++) {
            for (int j = 0; j < pts[i].length; j++) {
                pts[i][j] = Long.parseLong(next());
            }
        }

        int count = (int) n;
        long INF = 1000000000000000000L;
        long[] best = new long[count];
        Arrays.fill(best, INF);
        boolean[] used = new boolean[count];
        best[0] = 0;
        long total = 0;
        for (int round = 0; round < count; round++) {
            int u = -1;
            for (int v = 0; v < count; v++) {
                if (!used[v] && (u == -1 || best[v] < best[u])) u = v;
            }
            used[u] = true;
            total += best[u];
            for (int v = 0; v < count; v++) {
                if (!used[v]) {
                    long d = Math.abs(pts[u][0] - pts[v][0]) + Math.abs(pts[u][1] - pts[v][1]);
                    if (d < best[v]) best[v] = d;
                }
            }
        }
        System.out.println(total);
    }
}
